// writeConsumers durably replaces consumers.idx with the full table. The
// bytes land in a synced temp file before the atomic rename, exactly
// like writeTruncateMarker, so a crash leaves one complete image or the
// other. Every write is forced through here — checkpoint changes are
// durable even when Options.Sync is false.
func (l *Log) writeConsumers(entries []consumerEntry) error {
	path := l.consumersPath()
	tmp := path + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(encodeConsumers(entries)); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := syncFile(f); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		os.Remove(tmp)
		return err
	}
	_ = syncDir(l.dir)
	return nil
}

// consumersList snapshots the registration table as on-disk entries.
func (l *Log) consumersList() []consumerEntry {
	entries := make([]consumerEntry, 0, len(l.consumers))
	for name, seq := range l.consumers {
		entries = append(entries, consumerEntry{name: name, seq: seq})
	}
	return entries
}

// AckConsumer confirms consumer name's replay progress through seq and
// persists it durably. Consumers Scan from ConsumerSeq(name)+1, process,
// and call AckConsumer when the prefix is handled; seq therefore means
// "every batch with a sequence up to seq has been processed".
//
// A name is registered only by its first AckConsumer(name, 0); the
// initial confirmed sequence is zero. After that:
//
//   - seq equal to the stored value succeeds without writing.
//   - a greater seq advances the checkpoint; seq must name a committed
//     batch (a permanent hole may be skipped over, a group may be
//     confirmed as a unit), the batch must not already have been
//     reclaimed by DeleteThrough, and no still-staged batch may hold a
//     sequence below seq that the prefix claim would overrun.
//   - a smaller seq, an unknown/hole/staged/reclaimed target, or a
//     staged batch earlier in the sequence space returns ErrInvalidAck
//     and changes nothing.
//
// A syntactically invalid name returns ErrInvalidConsumer. A legal but
// unregistered name returns ErrUnknownConsumer (registration is only
// AckConsumer(name, 0)). A returned success is durable regardless of
// Options.Sync: the target and every earlier committed batch are
// fsynced first, then consumers.idx is atomically replaced and synced.
// An fsync or metadata write failure returns ErrCheckpointFailed, all
// consumer state stays at its previous value and the call retries.
func (l *Log) AckConsumer(name string, seq uint64) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return errClosed
	}
	if !validConsumerName(name) {
		return ErrInvalidConsumer
	}
	cur, registered := l.consumers[name]
	if !registered {
		if seq != 0 {
			return ErrUnknownConsumer
		}
	} else {
		switch {
		case seq == cur:
			// Confirming the already-confirmed prefix is an idempotent
			// no-op: no disk write and no extra fsync.
			return nil
		case seq < cur:
			// Checkpoints only move forward.
			return ErrInvalidAck
		}
	}
	if seq > 0 {
		if _, committed := l.index[seq]; !committed {
			// Unknown, a permanent hole, still staged, or already
			// reclaimed: reclaimed batches leave the index like unknown
			// ones (and Read distinguishes them as ErrTruncated), but for
			// a checkpoint every non-committed target is the same
			// ErrInvalidAck. Note a group that straddled a truncation
			// boundary can keep a batch with seq <= through readable, so
			// membership, not through, is the test.
			return ErrInvalidAck
		}
		for s, recs := range l.staged {
			if recs != nil && s < seq {
				// A staged batch ahead of the target would be claimed as
				// processed by the "prefix through seq" statement; its
				// reservation must commit first.
				return ErrInvalidAck
			}
		}
	}

	// Make the data durable before claiming it: a plain registration at
	// seq 0 persists the table only, while an advance must barrier the
	// target and every earlier committed batch even when Options.Sync is
	// false. The current segment goes through its live write handle;
	// rolled segments are closed and reopened just for the fsync. A
	// failure leaves the in-memory checkpoint untouched and the whole
	// call retryable.
	if seq > 0 {
		if err := l.syncDirtySegments(); err != nil {
			return err
		}
	}

	next := l.consumersList()
	if !registered {
		next = append(next, consumerEntry{name: name, seq: seq})
	} else {
		for i := range next {
			if next[i].name == name {
				next[i].seq = seq
				break
			}
		}
	}
	if err := l.writeConsumers(next); err != nil {
		// The new image never landed: the table on disk and in memory is
		// the previous one, and the segment syncs already performed only
		// made data more durable. Retry freely.
		return fmt.Errorf("%w: %v", ErrCheckpointFailed, err)
	}
	l.consumers[name] = seq
	return nil
}

// ConsumerSeq returns consumer name's last confirmed sequence, 0 for a
// freshly registered consumer. A syntactically invalid name returns
// ErrInvalidConsumer; a legal but unregistered name returns
// ErrUnknownConsumer.
func (l *Log) ConsumerSeq(name string) (uint64, error) {
	l.mu.RLock()
	defer l.mu.RUnlock()
	if l.closed {
		return 0, errClosed
	}
	if !validConsumerName(name) {
		return 0, ErrInvalidConsumer
	}
	seq, ok := l.consumers[name]
	if !ok {
		return 0, ErrUnknownConsumer
	}
	return seq, nil
}

// DropConsumer removes consumer name's registration durably, releasing
// any prefix protection it held. It returns ErrInvalidConsumer for a
// syntactically invalid name and ErrUnknownConsumer for a legal name
// that is not registered. A later AckConsumer(name, 0) registers the
// name again from zero; a reopen between the drop and the new
// registration never revives it.
func (l *Log) DropConsumer(name string) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return errClosed
	}
	if !validConsumerName(name) {
		return ErrInvalidConsumer
	}
	if _, ok := l.consumers[name]; !ok {
		return ErrUnknownConsumer
	}
	next := l.consumersList()
	for i := range next {
		if next[i].name == name {
			next = append(next[:i], next[i+1:]...)
			break
		}
	}
	if err := l.writeConsumers(next); err != nil {
		return fmt.Errorf("%w: %v", ErrCheckpointFailed, err)
	}
	delete(l.consumers, name)
	return nil
}

package log

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"sort"
	"unicode/utf8"
)

// The segment-level index lives in a sidecar file ("index.idx") next to
// the segments so that Open never has to decode every segment entry as
// the log grows. The sidecar is a derived, rebuildable cache: losing
// it, or finding it truncated, version-mismatched, checksum-bad or
// contradictory to the segments, only triggers a full rebuild from the
// segment files — never data loss and never a user-visible error.
//
// Layout, all integers little-endian:
//
//	header  8 bytes  "BCLIDX" (6 bytes) + uint16 version
//	records          length-prefixed, checksummed, in (segment, offset)
//	                 order:
//
//	  committed entry ("E"):
//	    8 bytes segment file number
//	    8 bytes offset of the entry's segment magic
//	    8 bytes length of the whole entry on disk (magic ... crc)
//	    4 bytes disk entry CRC (the checksum stored by the segment)
//	    4 bytes member count m
//	    1 byte  flags (bit 0: entry uses keyed framing — BCLI/BCLK)
//	    m × (8-byte seq, 8-byte body offset, 4-byte body length,
//	         2-byte key length, key bytes; key length 0 = anonymous)
//
// Version 1 sidecars (no flags byte and no key fields) are not
// interpreted: a version mismatch triggers the ordinary one-time rebuild
// from the segment files, exactly like any other invalid sidecar.
//
//	hole marker ("H"):
//	  8 bytes segment file number
//	  8 bytes offset of the marker's segment magic
//	  8 bytes length of the whole marker on disk
//	  4 bytes disk marker CRC
//	  4 bytes sequence count c
//	  c × 8-byte sequence
//
// Every record is framed as: 1-byte type, 4-byte body length, body,
// 4-byte CRC32 of type+length+body. A torn final record — the remnant
// of a crash between the index write and its sync — is discarded on the
// next open, and any such truncation makes Open rebuild from the
// segments instead. Records are appended only after the corresponding
// segment entry is durable, so an adopted index can never advertise a
// batch the segments do not contain; adoption re-verifies the physical
// layout and every disk CRC before trusting it.
var (
	indexMagic   = []byte{'B', 'C', 'L', 'I', 'D', 'X'}
	indexVersion = uint16(2)

	recEntry = byte('E')
	recHole  = byte('H')

	// entryFlagKeyed marks an E record whose segment entry uses keyed
	// framing (BCLI for a lone keyed commit, BCLK for a group containing
	// at least one keyed member).
	entryFlagKeyed = byte(1)
)

// indexEntry is one committed segment entry: either a single batch or a
// whole group, located on disk and carrying every member's index ref.
type indexEntry struct {
	seg     int
	off     int // offset of the entry's segment magic
	length  int // total length of the entry on disk, including its CRC
	diskCRC uint32
	keyed   bool // segment entry is BCLI/BCLK rather than BCL1/BCLG
	members []indexMember
}

type indexMember struct {
	seq    uint64
	id     string // idempotency key, "" for an anonymous member
	off    int    // body offset within the segment file
	length int    // body length
}

// indexHole is one durable BCLH marker on disk.
type indexHole struct {
	seg     int
	off     int
	length  int
	diskCRC uint32
	seqs    []uint64
}

type parsedIndex struct {
	entries []indexEntry
	holes   []indexHole
}

var errIndexInvalid = errors.New("log: invalid index sidecar")

// readIndexFile parses the sidecar bytes strictly. A truncated final
// record — the remnant of a crash between an index write and its sync —
// is reported as tailLen (the valid prefix length). Missing tail bytes
// are the only tolerated defect; bad framing, an unknown version or any
// checksum mismatch yield errIndexInvalid.
func readIndexFile(data []byte) (p parsedIndex, tailLen int, err error) {
	const headerLen = 8
	if len(data) < headerLen {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if string(data[:6]) != string(indexMagic) {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if binary.LittleEndian.Uint16(data[6:8]) != indexVersion {
		return parsedIndex{}, 0, errIndexInvalid
	}
	pos := headerLen
	for pos < len(data) {
		start := pos
		rest := data[pos:]
		if len(rest) < 10 {
			// type(1) + length(4) + crc(4) is the smallest record.
			return p, start, nil
		}
		kind := rest[0]
		bodyLen := int(binary.LittleEndian.Uint32(rest[1:5]))
		if bodyLen < 0 {
			return parsedIndex{}, 0, errIndexInvalid
		}
		total := 5 + bodyLen + 4 // type + length + body + crc
		if len(data)-start < total {
			// Any truncation of the last record is a crash tail.
			return p, start, nil
		}
		body := rest[5 : 5+bodyLen]
		crc := binary.LittleEndian.Uint32(rest[5+bodyLen : 9+bodyLen])
		if crc32.ChecksumIEEE(rest[:5+bodyLen]) != crc {
			return parsedIndex{}, 0, errIndexInvalid
		}
		bp := 0
		switch kind {
		case recEntry:
			const fixed = 8 + 8 + 8 + 4 + 4 + 1
			if bodyLen < fixed {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e := indexEntry{}
			e.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.off = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.length = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.diskCRC = binary.LittleEndian.Uint32(body[bp : bp+4])
			bp += 4
			m := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			flags := body[bp]
			bp++
			if flags & ^entryFlagKeyed != 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e.keyed = flags&entryFlagKeyed != 0
			if m <= 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e.members = make([]indexMember, m)
			for i := 0; i < m; i++ {
				if bodyLen-bp < 8+8+4+2 {
					return parsedIndex{}, 0, errIndexInvalid
				}
				mb := indexMember{
					seq:    binary.LittleEndian.Uint64(body[bp : bp+8]),
					off:    int(binary.LittleEndian.Uint64(body[bp+8 : bp+16])),
					length: int(binary.LittleEndian.Uint32(body[bp+16 : bp+20])),
				}
				bp += 20
				klen := int(binary.LittleEndian.Uint16(body[bp : bp+2]))
				bp += 2
				if !e.keyed && klen != 0 {
					return parsedIndex{}, 0, errIndexInvalid
				}
				if klen < 0 || klen > maxBatchIDLen || bodyLen-bp < klen {
					return parsedIndex{}, 0, errIndexInvalid
				}
				if klen > 0 {
					raw := body[bp : bp+klen]
					if bytes.IndexByte(raw, 0) >= 0 || !utf8.Valid(raw) {
						return parsedIndex{}, 0, errIndexInvalid
					}
					mb.id = string(raw)
					bp += klen
				}
				e.members[i] = mb
			}
			if bp != bodyLen {
				return parsedIndex{}, 0, errIndexInvalid
			}
			if e.seg <= 0 || e.off < 0 || e.length <= 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			p.entries = append(p.entries, e)
		case recHole:
			if bodyLen < 8+8+8+4+4 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h := indexHole{}
			h.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.off = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.length = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.diskCRC = binary.LittleEndian.Uint32(body[bp : bp+4])
			bp += 4
			c := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			if h.seg <= 0 || h.off < 0 || h.length <= 0 || c < 0 || 8*c != bodyLen-bp {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h.seqs = make([]uint64, c)
			for i := 0; i < c; i++ {
				h.seqs[i] = binary.LittleEndian.Uint64(body[bp : bp+8])
				bp += 8
			}
			p.holes = append(p.holes, h)
		default:
			return parsedIndex{}, 0, errIndexInvalid
		}
		pos = start + total
	}
	return p, 0, nil
}

// encodeIndexHeader returns the sidecar header.
func encodeIndexHeader() []byte {
	buf := make([]byte, 0, 8)
	buf = append(buf, indexMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint16(tmp[:2], indexVersion)
	return append(buf, tmp[:2]...)
}

// finishIndexRecord wraps a record body with its type tag, length and
// trailing checksum.
func finishIndexRecord(kind byte, body []byte) []byte {
	rec := make([]byte, 0, 5+len(body)+4)
	rec = append(rec, kind)
	var tmp [8]byte
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(body)))
	rec = append(rec, tmp[:4]...)
	rec = append(rec, body...)
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(rec))
	return append(rec, tmp[:4]...)
}

func putIndexU64(body *[]byte, tmp *[8]byte, v uint64) {
	binary.LittleEndian.PutUint64(tmp[:], v)
	*body = append(*body, tmp[:]...)
}

// encodeEntryRecord encodes one committed segment entry and its members.
func encodeEntryRecord(e indexEntry) []byte {
	size := 8 + 8 + 8 + 4 + 4 + 1
	for _, m := range e.members {
		size += 8 + 8 + 4 + 2 + len(m.id)
	}
	body := make([]byte, 0, size)
	var tmp [8]byte
	putIndexU64(&body, &tmp, uint64(e.seg))
	putIndexU64(&body, &tmp, uint64(e.off))
	putIndexU64(&body, &tmp, uint64(e.length))
	binary.LittleEndian.PutUint32(tmp[:4], e.diskCRC)
	body = append(body, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(e.members)))
	body = append(body, tmp[:4]...)
	flags := byte(0)
	if e.keyed {
		flags = entryFlagKeyed
	}
	body = append(body, flags)
	for _, m := range e.members {
		putIndexU64(&body, &tmp, m.seq)
		putIndexU64(&body, &tmp, uint64(m.off))
		binary.LittleEndian.PutUint32(tmp[:4], uint32(m.length))
		body = append(body, tmp[:4]...)
		binary.LittleEndian.PutUint16(tmp[:2], uint16(len(m.id)))
		body = append(body, tmp[:2]...)
		body = append(body, m.id...)
	}
	return finishIndexRecord(recEntry, body)
}

// encodeHoleRecord encodes one durable hole marker as seen in a segment.
func encodeHoleRecord(h indexHole) []byte {
	body := make([]byte, 0, 8+8+8+4+4+8*len(h.seqs))
	var tmp [8]byte
	putIndexU64(&body, &tmp, uint64(h.seg))
	putIndexU64(&body, &tmp, uint64(h.off))
	putIndexU64(&body, &tmp, uint64(h.length))
	binary.LittleEndian.PutUint32(tmp[:4], h.diskCRC)
	body = append(body, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(h.seqs)))
	body = append(body, tmp[:4]...)
	for _, seq := range h.seqs {
		putIndexU64(&body, &tmp, seq)
	}
	return finishIndexRecord(recHole, body)
}

// diskRecord is one physical on-disk item located by the index, merged
// in (segment, offset) order for the canonical snapshot.
type diskRecord struct {
	seg int
	off int
	enc []byte
}

// writeIndexSnapshot replaces the sidecar atomically with a full image
// of the recovered log: the header, then every committed entry and hole
// marker in (segment, offset) order. The temp file is fsynced before
// the rename; callers run this after the segment bytes it describes are
// synced. A lost rename only leaves the previous sidecar behind, which
// adoption validation rejects as contradictory, triggering a rebuild.
func (l *Log) writeIndexSnapshot(p parsedIndex) error {
	var recs []diskRecord
	for i := range p.entries {
		e := &p.entries[i]
		recs = append(recs, diskRecord{seg: e.seg, off: e.off, enc: encodeEntryRecord(*e)})
	}
	for i := range p.holes {
		h := &p.holes[i]
		recs = append(recs, diskRecord{seg: h.seg, off: h.off, enc: encodeHoleRecord(*h)})
	}
	sort.SliceStable(recs, func(i, j int) bool {
		if recs[i].seg != recs[j].seg {
			return recs[i].seg < recs[j].seg
		}
		return recs[i].off < recs[j].off
	})
	var buf []byte
	buf = append(buf, encodeIndexHeader()...)
	for _, r := range recs {
		buf = append(buf, r.enc...)
	}
	tmp := l.indexPath() + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(buf); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := syncFile(f); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, l.indexPath()); err != nil {
		os.Remove(tmp)
		return err
	}
	// Best effort: if the rename is not journaled and power loss keeps
	// the previous sidecar, adoption validation detects the divergence
	// and rebuilds, so snapshot correctness never depends on this sync.
	_ = syncDir(l.dir)
	return nil
}

// appendIndexRecord appends one record to the live sidecar after a
// commit's segment entry is durable. With Options.Sync it fsyncs the
// sidecar before returning. Any failure is returned to the caller,
// which rolls the just-written segment entry and this record back; an
// fsync failure is wrapped as ErrSyncFailed so commits keep their
// documented error semantics.
func (l *Log) appendIndexRecord(rec []byte) error {
	if l.idxFile == nil {
		return errIndexInvalid
	}
	if _, err := l.idxFile.Write(rec); err != nil {
		return err
	}
	l.idxSize += len(rec)
	if l.opts.Sync {
		if err := syncFile(l.idxFile); err != nil {
			return fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	return nil
}

// appendAbortRecord appends one hole record to the live sidecar after
// the abort's marker is durable, and always fsyncs the sidecar: an
// abort is durable regardless of Options.Sync. Any failure is returned
// to the caller, which rolls the segment marker and this record back,
// so a retry cannot duplicate either.
func (l *Log) appendAbortRecord(rec []byte) error {
	if l.idxFile == nil {
		return errIndexInvalid
	}
	if _, err := l.idxFile.Write(rec); err != nil {
		return err
	}
	l.idxSize += len(rec)
	return syncFile(l.idxFile)
}

// truncateIndex rolls the sidecar back to size n after a failed commit,
// mirroring the segment-entry rollback so no uncommitted record is left
// behind and a retry cannot duplicate it.
func (l *Log) truncateIndex(n int) {
	if l.idxFile == nil {
		return
	}
	if err := l.idxFile.Truncate(int64(n)); err != nil {
		// Best effort: an untidy sidecar is harmless. Open never trusts
		// it blindly and rebuilds from the segments on any contradiction.
		return
	}
	l.idxSize = n
}

// openIndex opens the live sidecar for append, creating it absent. The
// file has already been validated (or freshly snapshotted) by Open; an
// empty file (a log with no commits yet) gets its header first.
func (l *Log) openIndex() error {
	f, err := os.OpenFile(l.indexPath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	l.idxFile = f
	l.idxSize = int(st.Size())
	if l.idxSize == 0 {
		hdr := encodeIndexHeader()
		if _, err := f.Write(hdr); err != nil {
			f.Close()
			l.idxFile = nil
			return err
		}
		l.idxSize = len(hdr)
	}
	return nil
}

// readIndexBytes reads the whole sidecar. Used only by adoption.
func (l *Log) readIndexBytes() ([]byte, error) {
	f, err := os.Open(l.indexPath())
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return io.ReadAll(f)
}

	ErrBatchIDConflict = errors.New("log: batch id conflict")
	// ErrTruncated is returned by Read and Scan for a sequence whose
	// segment was reclaimed by a prefix truncation (DeleteThrough). It
	// is distinct from ErrUnknownBatch: the sequence was once committed,
	// and that fact survives restarts and index rebuilds.
	ErrTruncated = errors.New("log: sequence truncated")
	// ErrInvalidRetention is returned by DeleteThrough when its argument
	// is not a usable truncation point: a sequence that was never
	// committed, a hole, a still-staged batch, or a point past which
	// uncommitted staged or hole-marked reservations would be reclaimed
	// together with the history. Nothing is deleted when it is returned.
	ErrInvalidRetention = errors.New("log: invalid retention point")
	// ErrRetentionFailed is returned by DeleteThrough when persisting
	// the truncation point or removing the old segment files fails. The
	// log is left in one of its two consistent states — either the full
	// old state or the full new state — both of which stay readable; a
	// later reopen completes or discards the pending truncation.
	ErrRetentionFailed = errors.New("log: retention failed")
	// ErrInvalidConsumer is returned for a consumer name that fails the
	// idempotency-key naming rule (empty, NUL byte, invalid UTF-8 or
	// longer than 256 bytes). Consumer names and idempotency keys are
	// separate namespaces, but they share the rule.
	ErrInvalidConsumer = errors.New("log: invalid consumer name")
	// ErrUnknownConsumer is returned by AckConsumer, ConsumerSeq and
	// DropConsumer for a syntactically legal name that was never
	// registered. Registration happens only through AckConsumer(name, 0).
	ErrUnknownConsumer = errors.New("log: unknown consumer")
	// ErrInvalidAck is returned by AckConsumer when seq cannot confirm a
	// prefix: it moves a registered consumer backwards, names a batch
	// that is not committed (unknown, a permanent hole or still staged),
	// names history already reclaimed by DeleteThrough, or a still-staged
	// batch with a smaller sequence would be reclaimed together with the
	// confirmed prefix. Permanent holes above the confirmed prefix may be
	// skipped, and a group may be confirmed as a unit.
	ErrInvalidAck = errors.New("log: invalid ack")
	// ErrCheckpointFailed is returned when a checkpoint change cannot be
	// made durable: forcing the committed data to disk, writing or
	// syncing consumers.idx fails. No consumer state changes and the call
	// can be retried.
	ErrCheckpointFailed = errors.New("log: checkpoint failed")
	// ErrCorruptCheckpoint is returned by Open when consumers.idx is
	// present but cannot be trusted: truncated, checksum-bad, framed
	// wrongly, from an unsupported version or semantically impossible
	// (a confirmed sequence that is not committed, already reclaimed,
	// ahead of a staged batch, or duplicated). Progress is never reset
	// silently; the caller must intervene.
	ErrCorruptCheckpoint = errors.New("log: corrupt checkpoint")
	// ErrRetentionBlocked is returned by DeleteThrough when the reclaimable
	// prefix contains a batch above at least one consumer's confirmed
	// sequence. Nothing is deleted — no segment, index or idempotency key
	// changes — until every consumer has confirmed the prefix.
	ErrRetentionBlocked = errors.New("log: retention blocked by consumer")
	// ErrAbortFailed is returned by Abort when the hole marker or its
	// index record cannot be written or made durable. The batch and its
	// idempotency key stay staged under the original sequence, the
	// partial marker and index record are rolled back, and retrying the
	// abort — or committing the batch instead — cannot produce a
	// duplicate record.
	ErrAbortFailed = errors.New("log: abort failed")
)

var errClosed = errors.New("log: closed")

// syncFile fsyncs a file. It is a variable so tests can simulate
// sync failures.
var syncFile = func(f *os.File) error { return f.Sync() }

// removeFile deletes a file. It is a variable so tests can simulate
// segment removal failures during prefix truncation.
var removeFile = func(name string) error { return os.Remove(name) }

// Options configures a Log opened with Open.
type Options struct {
	// SegmentBytes is the capacity of one segment file in bytes. Once a
	// non-empty segment would exceed it, the log rolls to a new segment.
	// A single batch or group larger than the capacity occupies its own
	// segment. Must be positive.
	SegmentBytes int
	// Sync makes Commit and CommitGroup fsync the segment file before
	// returning, so a returned commit is durable.
	Sync bool
}

// Batch is a group of records identified by a single sequence number.
// A Batch returned by Append is staged; after Commit or CommitGroup it
// is readable. A batch staged with AppendIdempotent additionally
// carries the caller-chosen idempotency key, returned by ID; anonymous
// batches return "" from ID.
type Batch struct {
	seq     uint64
	id      string
	records [][]byte
	owner   *Log
}

// Seq returns the sequence number reserved for the batch.
func (b Batch) Seq() uint64 { return b.seq }

// ID returns the batch's idempotency key as given to
// AppendIdempotent, or "" for an anonymous batch staged with Append.
func (b Batch) ID() string { return b.id }

// Records returns a copy of the batch's records.
func (b Batch) Records() [][]byte { return copyRecords(b.records) }

// Segment describes one segment file by the committed sequences it holds.
type Segment struct {
	FirstSeq uint64
	LastSeq  uint64
}

// entryRef locates one committed batch body inside a segment file. The
// persistent index sidecar stores the same locations; its loss or
// invalidation is always safe because Open rebuilds it from the
// segments. gen is the publication generation of the commit that
// published the batch; every member of a group commit shares one gen,
// which lets a streaming replay snapshot see the whole group or none of
// it.
type entryRef struct {
	seg    int // segment file number
	off    int // offset of the batch body within the segment
	length int // length of the batch body
	gen    uint64
	id     string // idempotency key, "" for an anonymous batch
	keyed  bool   // body uses key framing (BCLI, or any BCLK member)
}

// Log is an append-only batch-commit log stored in a directory of
// segment files. It is safe for concurrent use, but the writer side is
// expected to be a single goroutine (see README Limits).
//
// The read and write paths are decoupled: writers take mu exclusively,
// while readers hold it only for the brief index and staged-state
// lookups. Segment file reads, decoding and user callbacks happen
// outside the lock, so a slow reader or a long replay never blocks a
// committing writer.
type Log struct {
	dir  string
	opts Options

	// mu guards the mutable index and write state below. Readers never
	// hold it across file I/O, decoding or callbacks.
	mu         sync.RWMutex
	file       *os.File // current segment, nil until first write
	fileSize   int
	idxFile    *os.File // index sidecar, opened for append
	idxSize    int
	segIndex   int // index of the current segment file, 0 = none yet
	curBatches int // committed batches in the current segment
	nextSeq    uint64
	staged     map[uint64][][]byte
