16	func reopen(t *testing.T, l *log.Log, dir string, opts log.Options) *log.Log {
17		t.Helper()
18		if err := l.Close(); err != nil {
19			t.Fatalf("Close: %v", err)
20		}
21		return open(t, dir, opts)
22	}
