24	func TestConsumerRegistrationAndLookup(t *testing.T) {
25		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
26	
27		if _, err := l.ConsumerSeq("svc-a"); !errors.Is(err, log.ErrUnknownConsumer) {
28			t.Fatalf("ConsumerSeq unknown = %v, want ErrUnknownConsumer", err)
29		}
30		if err := l.DropConsumer("svc-a"); !errors.Is(err, log.ErrUnknownConsumer) {
31			t.Fatalf("DropConsumer unknown = %v, want ErrUnknownConsumer", err)
32		}
33		if err := l.AckConsumer("svc-a", 1); !errors.Is(err, log.ErrUnknownConsumer) {
34			t.Fatalf("AckConsumer new name at 1 = %v, want ErrUnknownConsumer", err)
35		}
36		if err := l.AckConsumer("svc-a", 0); err != nil {
37			t.Fatalf("AckConsumer register: %v", err)
38		}
39		if got, err := l.ConsumerSeq("svc-a"); err != nil || got != 0 {
40			t.Fatalf("ConsumerSeq after register = %d, %v; want 0", got, err)
41		}
42		// Registering again with 0 is the same value: success, no progress.
43		if err := l.AckConsumer("svc-a", 0); err != nil {
44			t.Fatalf("repeat AckConsumer(0): %v", err)
45		}
46		if got, _ := l.ConsumerSeq("svc-a"); got != 0 {
47			t.Fatalf("seq = %d, want 0", got)
48		}
49	}
