51	func TestConsumerInvalidNames(t *testing.T) {
52		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
53		bad := []string{
54			"",
55			"has\x00nul",
56			string([]byte{0xff, 0xfe}), // invalid UTF-8
57			strings.Repeat("x", 257),
58		}
59		for _, name := range bad {
60			if err := l.AckConsumer(name, 0); !errors.Is(err, log.ErrInvalidConsumer) {
61				t.Errorf("AckConsumer(%q) = %v, want ErrInvalidConsumer", name, err)
62			}
63			if _, err := l.ConsumerSeq(name); !errors.Is(err, log.ErrInvalidConsumer) {
64				t.Errorf("ConsumerSeq(%q) = %v, want ErrInvalidConsumer", name, err)
65			}
66			if err := l.DropConsumer(name); !errors.Is(err, log.ErrInvalidConsumer) {
67				t.Errorf("DropConsumer(%q) = %v, want ErrInvalidConsumer", name, err)
68			}
69		}
70	}
