72	func TestConsumerNamespaceIndependentFromIdempotencyKeys(t *testing.T) {
73		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20, Sync: true})
74		b, err := l.AppendIdempotent("dup-name", [][]byte{[]byte("r")})
75		if err != nil {
76			t.Fatalf("AppendIdempotent: %v", err)
77		}
78		if _, err := l.Commit(b); err != nil {
79			t.Fatalf("Commit: %v", err)
80		}
81		// The same string is independently a legal, initially unknown
82		// consumer name.
83		if _, err := l.ConsumerSeq("dup-name"); !errors.Is(err, log.ErrUnknownConsumer) {
84			t.Fatalf("ConsumerSeq = %v, want ErrUnknownConsumer", err)
85		}
86		if err := l.AckConsumer("dup-name", 1); !errors.Is(err, log.ErrUnknownConsumer) {
87			t.Fatalf("Ack before register = %v, want ErrUnknownConsumer", err)
88		}
89		if err := l.AckConsumer("dup-name", 0); err != nil {
90			t.Fatalf("register consumer: %v", err)
91		}
92		if err := l.AckConsumer("dup-name", 1); err != nil {
93			t.Fatalf("AckConsumer(1): %v", err)
94		}
95	}
