97	func TestAckAdvanceRules(t *testing.T) {
98		dir := t.TempDir()
99		l := open(t, dir, log.Options{SegmentBytes: 1 << 20, Sync: true})
100		s1 := commit(t, l, []byte("one"))
101		if s1 != 1 {
102			t.Fatalf("seq = %d, want 1", s1)
103		}
104		if err := l.AckConsumer("c", 0); err != nil {
105			t.Fatalf("register: %v", err)
106		}
107	
108		if err := l.AckConsumer("c", 42); !errors.Is(err, log.ErrInvalidAck) {
109			t.Fatalf("ack unknown seq = %v, want ErrInvalidAck", err)
110		}
111		if err := l.AckConsumer("c", 1); err != nil {
112			t.Fatalf("ack 1: %v", err)
113		}
114		if got, _ := l.ConsumerSeq("c"); got != 1 {
115			t.Fatalf("seq = %d, want 1", got)
116		}
117		// Repeating the current value succeeds.
118		if err := l.AckConsumer("c", 1); err != nil {
119			t.Fatalf("repeat ack 1: %v", err)
120		}
121		// Checkpoints never move backwards, not even to zero.
122		if err := l.AckConsumer("c", 0); !errors.Is(err, log.ErrInvalidAck) {
123			t.Fatalf("rollback to 0 = %v, want ErrInvalidAck", err)
124		}
125	
126		// A staged batch with a lower sequence than the target blocks the
127		// prefix claim until it commits. Commit 3 first while 2 stays staged.
128		b2, err := l.Append([][]byte{[]byte("two")})
129		if err != nil {
130			t.Fatalf("Append: %v", err)
131		}
132		b3, err := l.Append([][]byte{[]byte("three")})
133		if err != nil {
134			t.Fatalf("Append: %v", err)
135		}
136		if _, err := l.Commit(b3); err != nil {
137			t.Fatalf("Commit b3: %v", err)
138		}
139		if err := l.AckConsumer("c", 3); !errors.Is(err, log.ErrInvalidAck) {
140			t.Fatalf("ack 3 past staged 2 = %v, want ErrInvalidAck", err)
141		}
142		if _, err := l.Commit(b2); err != nil {
143			t.Fatalf("Commit b2: %v", err)
144		}
145		if err := l.AckConsumer("c", 3); err != nil {
146			t.Fatalf("ack 3 after 2 commits: %v", err)
147		}
148	}
