150	func TestAckCrossesPermanentHoleAndConfirmsGroup(t *testing.T) {
151		dir := t.TempDir()
152		opts := log.Options{SegmentBytes: 1 << 20}
153		l := open(t, dir, opts)
154		commit(t, l, []byte("one")) // seq 1
155		l.Close()
156	
157		// Tear seq 2 into a permanent hole; reopen and commit seq 3.
158		appendTornEntry(t, dir, 2)
159		l = open(t, dir, opts)
160		b3, err := l.Append([][]byte{[]byte("three")})
161		if err != nil {
162			t.Fatalf("Append: %v", err)
163		}
164		if b3.Seq() != 3 {
165			t.Fatalf("seq = %d, want 3", b3.Seq())
166		}
167		if _, err := l.Commit(b3); err != nil {
168			t.Fatalf("Commit: %v", err)
169		}
170		if err := l.AckConsumer("c", 0); err != nil {
171			t.Fatalf("register: %v", err)
172		}
173		// The hole itself cannot anchor a prefix.
174		if err := l.AckConsumer("c", 2); !errors.Is(err, log.ErrInvalidAck) {
175			t.Fatalf("ack hole = %v, want ErrInvalidAck", err)
176		}
177		// A committed target past the permanent hole confirms the prefix.
178		if err := l.AckConsumer("c", 3); err != nil {
179			t.Fatalf("ack across hole: %v", err)
180		}
181	
182		// A whole group may be confirmed by its highest member.
183		g1, _ := l.Append([][]byte{[]byte("g1")})
184		g2, _ := l.Append([][]byte{[]byte("g2")})
185		seqs, err := l.CommitGroup([]log.Batch{g1, g2})
186		if err != nil {
187			t.Fatalf("CommitGroup: %v", err)
188		}
189		if !reflect.DeepEqual(seqs, []uint64{4, 5}) {
190			t.Fatalf("group seqs = %v, want [4 5]", seqs)
191		}
192		// A member in the middle of the group is itself a committed prefix
193		// anchor; the consumer is free to stop there.
194		if err := l.AckConsumer("mid", 0); err != nil {
195			t.Fatalf("register mid: %v", err)
196		}
197		if err := l.AckConsumer("mid", 4); err != nil {
198			t.Fatalf("ack mid-group member 4: %v", err)
199		}
200		if got, _ := l.ConsumerSeq("mid"); got != 4 {
201			t.Fatalf("mid seq = %d, want 4", got)
202		}
203		if err := l.AckConsumer("c", 5); err != nil {
204			t.Fatalf("ack group end: %v", err)
205		}
206		if got, _ := l.ConsumerSeq("c"); got != 5 {
207			t.Fatalf("seq = %d, want 5", got)
208		}
209	}
