211	func TestAckReclaimedTargetRejected(t *testing.T) {
212		dir := t.TempDir()
213		l := open(t, dir, log.Options{SegmentBytes: 32, Sync: true})
214		commit(t, l, []byte("one"))
215		commit(t, l, []byte("two"))
216		n, err := l.DeleteThrough(1)
