231	func TestConsumerScanFromConfirmedPlusOne(t *testing.T) {
232		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20, Sync: true})
233		for _, body := range []string{"a", "b", "c"} {
234			commit(t, l, []byte(body))
235		}
236		if err := l.AckConsumer("worker", 0); err != nil {
237			t.Fatalf("register: %v", err)
238		}
239		var got []string
240		from, err := l.ConsumerSeq("worker")
241		if err != nil {
242			t.Fatalf("ConsumerSeq: %v", err)
243		}
244		if err := l.Scan(from+1, func(b log.Batch) error {
245			got = append(got, string(b.Records()[0]))
246			return nil
247		}); err != nil {
248			t.Fatalf("Scan: %v", err)
249		}
250		if !reflect.DeepEqual(got, []string{"a", "b", "c"}) {
251			t.Fatalf("first scan = %v, want a b c", got)
252		}
253		if err := l.AckConsumer("worker", 2); err != nil {
254			t.Fatalf("ack 2: %v", err)
255		}
256		got = nil
257		from, _ = l.ConsumerSeq("worker")
258		if err := l.Scan(from+1, func(b log.Batch) error {
259			got = append(got, string(b.Records()[0]))
260			return nil
261		}); err != nil {
262			t.Fatalf("Scan: %v", err)
263		}
264		if !reflect.DeepEqual(got, []string{"c"}) {
265			t.Fatalf("second scan = %v, want [c]", got)
266		}
267	}
