269	func TestConsumerCheckpointPersistsAcrossReopenAndIndexLoss(t *testing.T) {
270		dir := t.TempDir()
271		opts := log.Options{SegmentBytes: 1 << 20}
272		l := open(t, dir, opts)
273		commit(t, l, []byte("one"))
274		commit(t, l, []byte("two"))
275		if err := l.AckConsumer("alpha", 0); err != nil {
276			t.Fatalf("register alpha: %v", err)
277		}
278		if err := l.AckConsumer("beta", 0); err != nil {
279			t.Fatalf("register beta: %v", err)
280		}
281		if err := l.AckConsumer("beta", 2); err != nil {
282			t.Fatalf("ack beta: %v", err)
283		}
284		if err := l.AckConsumer("alpha", 1); err != nil {
285			t.Fatalf("ack alpha: %v", err)
286		}
287	
288		// Plain reopen keeps every value.
289		l = reopen(t, l, dir, opts)
290		if got, err := l.ConsumerSeq("alpha"); err != nil || got != 1 {
291			t.Fatalf("alpha after reopen = %d, %v", got, err)
292		}
293		if got, err := l.ConsumerSeq("beta"); err != nil || got != 2 {
294			t.Fatalf("beta after reopen = %d, %v", got, err)
295		}
296	
297		// Deleting the rebuildable index sidecar must not lose checkpoints:
298		// consumers.idx is authoritative metadata.
299		if err := l.Close(); err != nil {
300			t.Fatalf("Close: %v", err)
301		}
302		if err := os.Remove(filepath.Join(dir, "index.idx")); err != nil {
303			t.Fatalf("remove index: %v", err)
304		}
305		l = open(t, dir, opts)
306		if got, _ := l.ConsumerSeq("alpha"); got != 1 {
307			t.Fatalf("alpha after index loss = %d, want 1", got)
308		}
309		if got, _ := l.ConsumerSeq("beta"); got != 2 {
310			t.Fatalf("beta after index loss = %d, want 2", got)
311		}
312	}
