328	func TestDropConsumerReleasesRegistration(t *testing.T) {
329		dir := t.TempDir()
330		opts := log.Options{SegmentBytes: 1 << 20}
331		l := open(t, dir, opts)
332		commit(t, l, []byte("one"))
333		if err := l.AckConsumer("c", 0); err != nil {
334			t.Fatalf("register: %v", err)
335		}
336		if err := l.AckConsumer("c", 1); err != nil {
337			t.Fatalf("AckConsumer: %v", err)
338		}
339		if err := l.DropConsumer("c"); err != nil {
340			t.Fatalf("DropConsumer: %v", err)
341		}
342		if _, err := l.ConsumerSeq("c"); !errors.Is(err, log.ErrUnknownConsumer) {
343			t.Fatalf("ConsumerSeq after drop = %v, want ErrUnknownConsumer", err)
344		}
345		if err := l.DropConsumer("c"); !errors.Is(err, log.ErrUnknownConsumer) {
346			t.Fatalf("drop again = %v, want ErrUnknownConsumer", err)
347		}
348		// Re-registering starts from zero.
349		if err := l.AckConsumer("c", 0); err != nil {
350			t.Fatalf("re-register: %v", err)
351		}
352		if got, _ := l.ConsumerSeq("c"); got != 0 {
353			t.Fatalf("re-registered seq = %d, want 0", got)
354		}
355		if err := l.AckConsumer("c", 1); err != nil {
356			t.Fatalf("ack after re-register: %v", err)
357		}
358		// A reopen must not revive the dropped registration nor lose the new
359		// one.
360		l = reopen(t, l, dir, opts)
361		if got, err := l.ConsumerSeq("c"); err != nil || got != 1 {
362			t.Fatalf("after reopen = %d, %v; want 1", got, err)
363		}
364		if err := l.DropConsumer("c"); err != nil {
365			t.Fatalf("drop: %v", err)
366		}
367		l = reopen(t, l, dir, opts)
368		if _, err := l.ConsumerSeq("c"); !errors.Is(err, log.ErrUnknownConsumer) {
369			t.Fatalf("dropped consumer revived by reopen: %v", err)
370		}
371	}
372	
373	func TestDeleteThroughBlockedUntilAllConsumersConfirm(t *testing.T) {
374		dir := t.TempDir()
375		opts := log.Options{SegmentBytes: 32, Sync: true}
376		l := open(t, dir, opts)
377		commit(t, l, []byte("one"))
378		commit(t, l, []byte("two"))
379		commit(t, l, []byte("three"))
380	
381		listSegs := func() []string {
382			files, err := filepath.Glob(filepath.Join(dir, "*.seg"))
383			if err != nil {
384				t.Fatal(err)
385			}
386			sort.Strings(files)
387			return files
388		}
389		before := listSegs()
390		if len(before) != 3 {
391			t.Fatalf("segments = %v, want 3", before)
392		}
393	
394		if err := l.AckConsumer("slow", 0); err != nil {
395			t.Fatalf("register slow: %v", err)
396		}
397		if err := l.AckConsumer("fast", 0); err != nil {
398			t.Fatalf("register fast: %v", err)
399		}
400		if err := l.AckConsumer("fast", 3); err != nil {
401			t.Fatalf("fast ack: %v", err)
402		}
403	
404		// The fast consumer alone does not unlock the prefix: slow is still
405		// at 0 and segment 1 carries batch 1.
406		n, err := l.DeleteThrough(1)
407		if !errors.Is(err, log.ErrRetentionBlocked) {
408			t.Fatalf("DeleteThrough = %d, %v; want ErrRetentionBlocked", n, err)
409		}
410		if after := listSegs(); !reflect.DeepEqual(after, before) {
411			t.Fatalf("files changed on block: before=%v after=%v", before, after)
412		}
413		// Data, index and idempotency keys are untouched: reads still work.
414		if got, err := l.Read(1); err != nil || string(got[0]) != "one" {
415			t.Fatalf("Read(1) after block = %q, %v", got, err)
416		}
417	
418		// Once the lagging consumer confirms, the same call reclaims.
419		if err := l.AckConsumer("slow", 1); err != nil {
420			t.Fatalf("slow ack: %v", err)
421		}
422		n, err = l.DeleteThrough(1)
423		if err != nil || n != 1 {
424			t.Fatalf("DeleteThrough after confirm = %d, %v", n, err)
425		}
426		if len(listSegs()) != 2 {
427			t.Fatalf("segments after delete = %v, want 2", listSegs())
428		}
429	
430		// Prefix up through 3 still contains batches above both checkpoints;
431		// advancing fast only is not enough.
432		n, err = l.DeleteThrough(3)
433		if !errors.Is(err, log.ErrRetentionBlocked) {
434			t.Fatalf("DeleteThrough(3) = %d, %v; want ErrRetentionBlocked", n, err)
435		}
436		// Dropping the lagging consumer removes its protection.
437		if err := l.DropConsumer("slow"); err != nil {
438			t.Fatalf("DropConsumer: %v", err)
439		}
440		n, err = l.DeleteThrough(3)
441		if err != nil || n != 2 {
442			t.Fatalf("DeleteThrough after drop = %d, %v; want 2", n, err)
443		}
444		if len(listSegs()) != 0 {
445			t.Fatalf("segments = %v, want none", listSegs())
446		}
447	}
448	
449	func TestDeleteThroughValidationUnchangedWithConsumers(t *testing.T) {
450		l := open(t, t.TempDir(), log.Options{SegmentBytes: 32, Sync: true})
451		commit(t, l, []byte("one"))
452		if err := l.AckConsumer("c", 0); err != nil {
453			t.Fatalf("register: %v", err)
454		}
455		// seq 0 remains a no-op returning zero.
456		if n, err := l.DeleteThrough(0); err != nil || n != 0 {
457			t.Fatalf("DeleteThrough(0) = %d, %v", n, err)
458		}
459		// An unknown anchor keeps returning ErrInvalidRetention even though a
460		// consumer protects nothing there.
461		if _, err := l.DeleteThrough(99); !errors.Is(err, log.ErrInvalidRetention) {
462			t.Fatalf("DeleteThrough(99) = %v, want ErrInvalidRetention", err)
463		}
464	}
465	
466	func TestDeleteThroughHoleOnlySegmentNotProtected(t *testing.T) {
467		dir := t.TempDir()
468		// A capacity of one byte makes the first commit after tail recovery
469		// roll to segment 2, leaving segment 1 hole-only.
470		opts := log.Options{SegmentBytes: 1}
471		open(t, dir, opts).Close()
472		// seq 1 dies in a torn first entry in a manually created segment 1:
473		// the segment becomes hole-only on reopen, and the first successful
474		// batch lands in segment 2 at seq 2.
475		var entry []byte
476		var tmp [8]byte
477		entry = append(entry, 'B', 'C', 'L', '1')
478		binary.LittleEndian.PutUint64(tmp[:], 1)
479		entry = append(entry, tmp[:]...)
480		binary.LittleEndian.PutUint32(tmp[:4], 1)
481		entry = append(entry, tmp[:4]...)
482		binary.LittleEndian.PutUint32(tmp[:4], 100)
483		entry = append(entry, tmp[:4]...)
484		entry = append(entry, []byte("only-a-prefix-of-the-record")...)
485		f, err := os.OpenFile(filepath.Join(dir, "000001.seg"), os.O_CREATE|os.O_WRONLY, 0o644)
486		if err != nil {
487			t.Fatal(err)
488		}
489		if _, err := f.Write(entry); err != nil {
490			t.Fatal(err)
491		}
492		if err := f.Close(); err != nil {
493			t.Fatal(err)
494		}
495		l := open(t, dir, opts)
496		if seq := commit(t, l, []byte("two")); seq != 2 {
497			t.Fatalf("seq = %d, want 2", seq)
498		}
499		// A consumer that has confirmed batch 2 protects neither the
500		// hole-only segment nor segment 2; the hole marker reserves no data.
501		if err := l.AckConsumer("c", 0); err != nil {
502			t.Fatalf("register: %v", err)
503		}
504		if err := l.AckConsumer("c", 2); err != nil {
505			t.Fatalf("ack 2 across hole: %v", err)
506		}
507		files, _ := filepath.Glob(filepath.Join(dir, "*.seg"))
508		sort.Strings(files)
509		if len(files) != 2 {
510			t.Fatalf("segments = %v, want 2", files)
511		}
512		n, err := l.DeleteThrough(2)
513		if err != nil {
514			t.Fatalf("DeleteThrough = %d, %v", n, err)
515		}
516		if n != 2 {
517			t.Fatalf("deleted = %d, want 2 (hole-only + committed segment)", n)
518		}
519		if _, err := l.ConsumerSeq("c"); err != nil {
520			t.Fatalf("consumer lost after reclaim: %v", err)
521		}
522		// Reopen: consumer state intact, seq 1 stays a permanent hole.
523		l = reopen(t, l, dir, opts)
524		if got, err := l.ConsumerSeq("c"); err != nil || got != 2 {
525			t.Fatalf("seq after reopen = %d, %v; want 2", got, err)
526		}
527		if seq := commit(t, l, []byte("three")); seq != 3 {
528			t.Fatalf("seq = %d, want 3 (hole 1 not reused)", seq)
529		}
530	}
