		t.Fatalf("same seq same state: %v", err)
	}
	if err := l.AckConsumerState("c", 1, []byte("s1-other")); !errors.Is(err, log.ErrCheckpointConflict) {
		t.Fatalf("same seq different state = %v, want ErrCheckpointConflict", err)
	}
